**GROUP TWO - TASK III (10 marks)**

The C program and the Pascal program below do the same job (the printed line numbers are not part of the programs; the questions quote the printed numbering: line 17 of the C program and line 18 of the Pascal program).

**C program**

```c
#include <stdio.h>
int main() {
    int bmonth, byear, cmonth, cyear, age;
    printf("Enter your birth month: ");
    scanf("%d", &bmonth);
    printf("Enter your birth year: ");
    scanf("%d", &byear);
    printf("Enter current month: ");
    scanf("%d", &cmonth);
    printf("Enter current year: ");
    scanf("%d", &cyear);
    if (bmonth <= cmonth)
        age = cyear - byear;
    else age = cyear - byear - 1;
    if (age < 13)
        printf("Hello child, you are %d years old.\n",age);
    if ((age > 12) && (age < 20))
        printf("Hello teen, you are %d years old.\n",age);
    if (age > 19)
        printf("Hello adult, you are %d years old.\n",age);
    getchar();
}
```

**Pascal program**

```pascal
program Ages;
var
    bmonth, byear, cmonth, cyear, age: integer;
begin
    write('Enter your birth month: ');
    readln(bmonth);
    write ('Enter your birth year: ');
    readln (byear);
    write ('Enter current month: ');
    readln (cmonth);
    write ('Enter current year: ');
    readln (cyear);
    if (bmonth <= cmonth) then
        age := cyear - byear
    else age := cyear - byear - 1;
    if (age < 13) then
        writeln('Hello child, you are ', age, ' years old.');
    if ((age > 12) and (age < 20)) then
        writeln('Hello teen, you are ', age, ' years old.');
    if (age > 19) then
        writeln('Hello adult, you are ', age, ' years old.');
    readln;
end.
```
